class Solution{public boolean isAdditiveNumber(String s){int n=s.length();for(int i=1;i<n;i++){if(s.charAt(0)=='0'&&i>1)break;for(int j=i+1;j<n;j++){if(s.charAt(i)=='0'&&j-i>1)break;try{long a=Long.parseLong(s.substring(0,i)),b=Long.parseLong(s.substring(i,j));int p=j;while(p<n){String x=Long.toString(a+b);if(!s.startsWith(x,p))break;p+=x.length();long c=a+b;a=b;b=c;}if(p==n)return true;}catch(Exception e){}}}return false;}}
